  sequencia: 2,
  tipo: 'LanceAceito',
  leilaoId: id,
  ocorridoEm: T,
  dados: { participante, valor },
});
const encerrado = (id: string, vencedor: string | null, valor: number | null): Evento => ({
  sequencia: 9,
  tipo: 'LeilaoEncerrado',
  leilaoId: id,
