    const e = rodar([criado('A', 'Bike'), lance('A', 'ana', 100), lance('A', 'bia', 110)]);
    expect(notificacoesDe(e, 'ana')).toEqual([
      { tipo: 'LANCE_SUPERADO', leilaoId: 'A', titulo: 'Bike', valorAnterior: 100, novoValor: 110, ocorridoEm: T },
